(34132, 'ptBR', 'Vinheta: Batedor Buscassangue', '', '', '', '', '', '', '', '', 19865),
(34133, 'ptBR', 'Vinheta: O Espancador', '', '', '', '', '', '', '', '', 19865),
(34134, 'ptBR', 'Vinheta: Quatro amigos completo', '', '', '', '', '', '', '', '', 19865),
